pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(hello) = bytes.strip_prefix("v:2|hello|") {
        return Ok(Msg::Hello(hello.into()));
    }
    if let Some(heartbeat) = bytes.strip_prefix("v:2|heartbeat|") {
        if let Ok(sequence) = heartbeat.parse() {
            return Ok(Msg::Heartbeat(sequence));
        }
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("v:2|hello|{}", value),
        Msg::Heartbeat(sequence) => format!("v:2|heartbeat|{}", sequence),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::{decode, Msg};

    #[test]
    fn hello_roundtrips_in_v2_envelope() {
        let msg = Msg::Hello("Ada".into());
        assert_eq!(super::encode(&msg), "v:2|hello|Ada");
        assert!(matches!(decode("v:2|hello|Ada"), Ok(Msg::Hello(name)) if name == "Ada"));
    }

    #[test]
    fn heartbeat_roundtrips_in_v2_envelope() {
        let msg = Msg::Heartbeat(42);
        assert_eq!(super::encode(&msg), "v:2|heartbeat|42");
        assert!(matches!(decode("v:2|heartbeat|42"), Ok(Msg::Heartbeat(sequence)) if sequence == 42));
    }
}
